require_once __DIR__.'/common.php';$id=(int)($_GET['id']??0);$sql="SELECT t.*,d.member_id,d.full_name,d.phone,d.nic,d.email FROM daham_pasala_teachers t JOIN dayakayan d ON d.id=t.dayakaya_id";$params=[];if($id){$sql.=' WHERE t.id=?';$params[]=$id;}$sql.=' ORDER BY d.full_name';$s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll();if($id&&!$rows){http_response_code(404);exit('Not found');}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function qs($r){$v=json_decode($r['qualifications']??'[]',true);return is_array($v)?$v:[];}
?><!doctype html><html lang="si"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher report</title><style>body{font-family:Arial,'Noto Sans Sinhala',sans-serif;color:#222;margin:24px}h1{font-size:22px} .top{display:flex;justify-content:space-between;align-items:center}.person{border:1px solid #bbb;border-radius:8px;padding:16px;margin:16px 0;break-inside:avoid}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.item{padding:8px;background:#f5f5f5;border-radius:4px}.muted{color:#666;font-size:12px}@media print{.no-print{display:none}body{margin:10mm}.person{break-inside:avoid}}@media(max-width:600px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><div class="top"><div><h1>දහම් පාසල් ගුරු වාර්තාව</h1><div class="muted">Temple Data Management System · <?=date('Y-m-d')?></div></div><button class="no-print" onclick="window.print()">Download / Save as PDF</button></div><?php foreach($rows as $r):$dt=!empty($r['start_date'])?new DateTime($r['start_date']):null;$diff=$dt?$dt->diff(new DateTime('today')):null;?><section class="person"><h2><?=h($r['full_name'])?></h2><div class="grid"><?php $fields=['දායක අංකය'=>$r['member_id'],'NIC'=>$r['nic'],'දුරකථනය'=>$r['phone'],'විෂය'=>$r['subject'],'තනතුර'=>$r['teacher_role'],'තත්ත්වය'=>$r['status']==='active'?'සක්‍රීය':'අක්‍රීය','සේවා ආරම්භක දිනය'=>$dt?$dt->format('Y-m-d'):'—','වර්ෂය'=>$dt?$dt->format('Y'):'—','මාසය'=>$dt?$dt->format('F'):'—','සේවා කාලය'=>$diff?($diff->y.' වසර, '.$diff->m.' මාස'):'—','Email'=>$r['email']];foreach($fields as $k=>$v):?><div class="item"><b><?=h($k)?></b><br><?=h($v?:'—')?></div><?php endforeach;?></div><p><b>අධ්‍යාපන සුදුසුකම්:</b> <?=h(implode('、',qs($r))?:'ඇතුළත් කර නැත')?></p><p><b>සටහන්:</b> <?=nl2br(h($r['notes']?:'—'))?></p></section><?php endforeach;?><?php if(!$rows):?><p>ගුරුවරුන් හමු නොවීය.</p><?php endif;?><script>window.addEventListener('load',()=>{if(new URLSearchParams(location.search).get('autoprint')==='1')window.print()})</script></body></html>